style.css:
/* OPPOSITION.EXE — Discord */

/* Change these colors if you want */
:root {
  --my-red: #ff2020;
  --my-black: #080808;
  --my-dark: #111111;
  --my-white: #eeeeee;
}

/* Main Discord background */
body,
[class*="appMount"] {
  background: var(--my-black) !important;
}

/* Dark panels */
[class*="sidebar"],
[class*="chatContent"],
[class*="members"],
[class*="panels"] {
  background: var(--my-dark) !important;
}

/* Red accents and links */
a,
[class*="selected"],
[class*="mention"] {
  color: var(--my-red) !important;
}

/* Message appearance */
[class*="message"] {
  border-radius: 9px !important;
}

/* Red hover glow */
[class*="clickable"]:hover {
  box-shadow: 0 0 8px #ff202055 !important;
}

/* Rounded avatars */
[class*="avatar"] {
  border-radius: 35% !important;
}
